// Validates and normalizes the incoming customer request. No external calls.
const LIMITS = { customer_name: 100, phone_number: 25, delivery_address: 300, area_name: 100, notes: 500 };

// Shared phone normalization: strip spaces, hyphens, dots and parentheses only.
// Leading zeros and a leading + country code are preserved as-is.
const normalizePhone = function (v) { return String(v).trim().replace(/[\s\-().]/g, ''); };

const raw = $input.first().json || {};
let body = raw.body;
if (typeof body === 'string') {
  try { body = JSON.parse(body); } catch (e) { body = null; }
}

const errors = [];
if (!body || typeof body !== 'object' || Array.isArray(body)) {
  errors.push('Request body must be a JSON object.');
  body = {};
}

const requiredText = function (field) {
  const v = body[field];
  if (v === undefined || v === null) { errors.push(field + ' is required.'); return null; }
  if (typeof v !== 'string') { errors.push(field + ' must be a string.'); return null; }
  const t = v.trim().replace(/\s+/g, ' ');
  if (t.length === 0) { errors.push(field + ' must not be empty.'); return null; }
  if (t.length > LIMITS[field]) { errors.push(field + ' must be at most ' + LIMITS[field] + ' characters.'); return null; }
  return t;
};

const customer_name = requiredText('customer_name');
const delivery_address = requiredText('delivery_address');
const area_name = requiredText('area_name');

let phone_number = null;
const rawPhone = requiredText('phone_number');
if (rawPhone !== null) {
  const p = normalizePhone(rawPhone);
  if (!/^\+?[0-9]{7,15}$/.test(p)) {
    errors.push('phone_number must contain 7 to 15 digits (an optional leading + is allowed; spaces, hyphens and parentheses are ignored).');
  } else {
    phone_number = p;
  }
}

let notes = '';
if (body.notes !== undefined && body.notes !== null) {
  if (typeof body.notes !== 'string') {
    errors.push('notes must be a string when provided.');
  } else if (body.notes.trim().length > LIMITS.notes) {
    errors.push('notes must be at most ' + LIMITS.notes + ' characters.');
  } else {
    notes = body.notes.trim();
  }
}

if (errors.length > 0) {
  return [{ json: {
    valid: false,
    statusCode: 400,
    body: {
      success: false,
      error: 'invalid_request',
      message: 'Invalid customer request: ' + errors.join(' '),
      details: errors,
    },
  } }];
}

return [{ json: {
  valid: true,
  customer: { customer_name: customer_name, phone_number: phone_number, delivery_address: delivery_address, area_name: area_name, notes: notes },
} }];

// Identifies the customer by normalized phone number. Does not write anything.
try {
  const incoming = $('Validate Customer Request').first().json.customer;
  const items = $input.all();

  const fail = function (statusCode, error, message, extra) {
    const body = Object.assign({ success: false, error: error, message: message }, extra || {});
    return [{ json: { route: 'error', statusCode: statusCode, body: body } }];
  };

  // Google Sheets read failure: never fall through to creating a customer blindly.
  if (items.some(function (i) { return i && i.json && i.json.error; })) {
    return fail(503, 'database_unavailable', 'The customer database could not be read right now. Please try again shortly.');
  }

  // Empty sheet yields a single empty item; drop it.
  const rows = items
    .map(function (i) { return i && i.json ? i.json : {}; })
    .filter(function (r) { return Object.keys(r).length > 0; });

  if (rows.length > 0) {
    const present = {};
    rows.forEach(function (r) { Object.keys(r).forEach(function (k) { present[k] = true; }); });
    const missing = ['customer_id', 'phone_number'].filter(function (c) { return !present[c]; });
    if (missing.length > 0) {
      return fail(500, 'configuration_error', 'The Customers sheet is missing required columns: ' + missing.join(', ') + '.');
    }
  }

  const str = function (v) { return v === null || v === undefined ? '' : String(v).trim(); };
  // Same normalization as the validation step.
  const normalizePhone = function (v) { return str(v).replace(/[\s\-().]/g, ''); };
  const sameText = function (a, b) {
    return str(a).replace(/\s+/g, ' ').toLowerCase() === str(b).replace(/\s+/g, ' ').toLowerCase();
  };

  const matches = rows.filter(function (r) { return normalizePhone(r.phone_number) === incoming.phone_number; });

  if (matches.length > 1) {
    return fail(409, 'duplicate_customer_records', 'Multiple customer records share this phone number. The Customers sheet must be corrected before this customer can be used.', {
      phone_number: incoming.phone_number,
      matching_customer_ids: matches.map(function (r) { return str(r.customer_id); }),
    });
  }

  const existingIds = {};
  rows.forEach(function (r) { const id = str(r.customer_id); if (id) existingIds[id] = (existingIds[id] || 0) + 1; });

  if (matches.length === 0) {
    // Prepare a new customer. ID format: C + UTC timestamp + 4 random chars, checked against existing IDs.
    let newId = '';
    for (let attempt = 0; attempt < 10; attempt++) {
      const ts = new Date().toISOString().replace(/[-:TZ.]/g, '').slice(0, 14);
      const rand = Math.random().toString(36).slice(2, 6).toUpperCase().padEnd(4, '0');
      const candidate = 'C' + ts + rand;
      if (!existingIds[candidate]) { newId = candidate; break; }
    }
    if (!newId) {
      return fail(500, 'id_generation_failed', 'A unique customer ID could not be generated. Please try again.');
    }
    return [{ json: {
      route: 'create',
      record: {
        customer_id: newId,
        customer_name: incoming.customer_name,
        phone_number: incoming.phone_number,
        delivery_address: incoming.delivery_address,
        area_name: incoming.area_name,
        created_at: new Date().toISOString(),
        notes: incoming.notes,
      },
    } }];
  }

  const existing = matches[0];
  const customerId = str(existing.customer_id);
  if (!customerId) {
    return fail(500, 'data_integrity_error', 'The matching customer record has no customer_id, so it cannot be safely reused or updated.');
  }
  if (existingIds[customerId] > 1) {
    return fail(409, 'duplicate_customer_id', 'The customer_id ' + customerId + ' appears on more than one row. The Customers sheet must be corrected first.');
  }

  const addressChanged = !sameText(existing.delivery_address, incoming.delivery_address);
  const areaChanged = !sameText(existing.area_name, incoming.area_name);
  const changed = addressChanged || areaChanged;

  // Name, phone, notes, customer_id and created_at always keep their stored values.
  return [{ json: {
    route: changed ? 'update' : 'reuse',
    changed_fields: [].concat(addressChanged ? ['delivery_address'] : [], areaChanged ? ['area_name'] : []),
    record: {
      customer_id: customerId,
      customer_name: str(existing.customer_name),
      phone_number: str(existing.phone_number),
      delivery_address: addressChanged ? incoming.delivery_address : str(existing.delivery_address),
      area_name: areaChanged ? incoming.area_name : str(existing.area_name),
      created_at: str(existing.created_at),
      notes: str(existing.notes),
    },
  } }];
} catch (err) {
  return [{ json: { route: 'error', statusCode: 500, body: {
    success: false, error: 'internal_error', message: 'Something went wrong while looking up the customer. Please try again.',
  } } }];
}

// Builds one consistent response for created / updated / reused customers.
try {
  const found = $('Find Customer by Phone').first().json;
  const r = found.record || {};
  const route = found.route;
  const result = $input.first() ? $input.first().json : {};

  const dbWriteFailed = function (verb) {
    return [{ json: { statusCode: 503, body: {
      success: false,
      error: 'database_write_failed',
      message: 'The customer record could not be ' + verb + ' in the database. No changes were confirmed. Please try again.',
    } } }];
  };

  if (route === 'create' || route === 'update') {
    // Only report success when the sheet write returned the row we wrote.
    const writeOk = result && !result.error && String(result.customer_id || '').trim() === r.customer_id;
    if (!writeOk) return dbWriteFailed(route === 'create' ? 'created' : 'updated');
  } else if (route !== 'reuse') {
    return [{ json: { statusCode: 500, body: { success: false, error: 'internal_error', message: 'Unexpected customer action.' } } }];
  }

  const action = route === 'create' ? 'created' : route === 'update' ? 'updated' : 'reused';
  const messages = {
    created: 'New customer created.',
    updated: 'Existing customer found; delivery details updated (' + (found.changed_fields || []).join(', ') + ').',
    reused: 'Existing customer found; no changes needed.',
  };

  return [{ json: { statusCode: 200, body: {
    success: true,
    action: action,
    customer_id: r.customer_id,
    customer_name: r.customer_name,
    phone_number: r.phone_number,
    delivery_address: r.delivery_address,
    area_name: r.area_name,
    created_at: r.created_at,
    message: messages[action],
  } } }];
} catch (err) {
  return [{ json: { statusCode: 500, body: {
    success: false, error: 'internal_error', message: 'Something went wrong while finalizing the customer record.',
  } } }];
}
